package com.ethk3.novaonepro.strategyv2;
import org.junit.Test;import static org.junit.Assert.*;import java.util.*;
public class RepairMatrixEvidenceR30Test {
 @Test public void eightKindsComputeActualDistinctTypedResearchProducts(){EvalContextR27 c=RepairObservatoryR30Test.ctx();PolicySpecR27 p=RepairObservatoryR30Test.parent(),q=p.withAst(PolicyAstR27.op("zscore",PolicyAstR27.leaf("cross",3,1)),p.meta);Set<String> hashes=new HashSet<>();for(String kind:Arrays.asList("EVIDENCE_TEACHER","TEACHER_DIVERSITY","ALGORITHM_COMPLEMENTARITY","FORWARD_REASONING","CONTRADICTION","REVERSE_REASONING","INVARIANCE","ACTION_UTILITY")){MatrixTensorR30R1.Tensor t=MatrixEvidenceR30R1.compute(kind,c,Arrays.asList(p,q,p),1);assertNotNull(kind,t);assertEquals(kind,t.kind);assertEquals("SELECT",t.role);assertTrue(t.cells>0);assertTrue(hashes.add(t.hash));assertTrue(t.payload.contains("formalLabelsRead"));assertFalse(t.payload.contains("F23_VM_TEACHER_VERIFIED"));}assertEquals(8,hashes.size());}
 @Test public void invarianceOnlyUsesPreregisteredLegalTransformsAndMissingTeacherIsNotMadeUp(){EvalContextR27 c=RepairObservatoryR30Test.ctx();assertNull(MatrixEvidenceR30R1.compute("EVIDENCE_TEACHER",c,Collections.emptyList(),1));PolicySpecR27 p=RepairObservatoryR30Test.parent();MatrixTensorR30R1.Tensor t=MatrixEvidenceR30R1.compute("INVARIANCE",c,Collections.singletonList(p),1);Map<?,?> frame=(Map<?,?>)JsonR27.parse(t.payload);List<?> values=(List<?>)frame.get("values");List<?> row=(List<?>)values.get(0);assertEquals(1,((Number)row.get(0)).doubleValue(),0);assertEquals(1,((Number)row.get(1)).doubleValue(),0);assertEquals(0,((Number)row.get(2)).doubleValue(),0);}
}
